const currentCount = $input.item.json.alert_count || 1;

return [
  {
    json: {
      ...$input.item.json,
      alert_count: currentCount + 1
    }
  }
];

console.log('⚠️ Duplicate lead detected. Halting pipeline to prevent double-billing and duplicate CRM records.');
return [
  {
    json: {
      status: 'DUPLICATE_HALTED',
      email: $input.item.json.fields?.Email,
      airtable_existing_id: $input.item.json.id,
      halted_at: new Date().toISOString()
    }
  }
];

const item = $input.item.json;

// Safely get meta_capi_data (whether with or without .body)
const capiData = item.meta_capi_data || item.body?.meta_capi_data;

// Safely get client IP and user agent from the Webhook headers
const headers = $('Webhook').item.json.headers || {};
const clientIp = headers["x-real-ip"] || headers["cf-connecting-ip"] || capiData?.user_data?.client_ip_address;
const userAgent = headers["user-agent"] || capiData?.user_data?.client_user_agent;
const leadId = item.lead_id || item.body?.lead_id;

return [{
  json: {
    data: [
      {
        ...capiData,
        user_data: {
          ...capiData?.user_data,
          client_ip_address: clientIp,
          client_user_agent: userAgent,
          external_id: [leadId]
        }
      }
    ]
  }
}];

const merged = $input.item.json;

// Check Downstream Sinks
const isMetaSuccess = !!merged.events_received;
const isAirtableSuccess = !!merged.id;

// Determine State according to your State Machine
let state = 'COMPLETED';
let failureDetails = [];

if (isMetaSuccess && isAirtableSuccess) {
  state = 'COMPLETED';
} else if (isAirtableSuccess && !isMetaSuccess) {
  state = 'RETRY_PENDING';
  failureDetails.push('Meta CAPI Delivery Failed (Network timeout or rate limit)');
} else if (!isAirtableSuccess && isMetaSuccess) {
  state = 'RETRY_PENDING';
  failureDetails.push('Airtable Database Ingestion Failed');
} else {
  state = 'PERMANENT_FAILURE';
  failureDetails.push('CRITICAL: Both Airtable and Meta CAPI Failed');
}

return [
  {
    json: {
      ...merged,
      reconciliation_state: state,
      meta_success: isMetaSuccess,
      airtable_success: isAirtableSuccess,
      failure_reason: failureDetails.join(' | ') || 'None',
      reconciled_at: new Date().toISOString()
    }
  }
];

